fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    // Initialize with the first element in [0..=end]
    let mut max_val = v[0];
    let mut max_idx = 0;

    // Scan the rest of the prefix
    for i in 1..=end {
        if v[i] > max_val {
            max_val = v[i];
            max_idx = i;
        }
    }

    (max_val, max_idx)
}

fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    // Initialize with the first element in [start..v.len())
    let mut min_val = v[start];
    let mut min_idx = start;

    // Scan the rest of the suffix
    for i in (start + 1)..v.len() {
        if v[i] < min_val {
            min_val = v[i];
            min_idx = i;
        }
    }

    (min_val, min_idx)
}

fn barrier(v: &[i32], p: usize) -> bool {
    // If p is the last index, there is no right-side element,
    // so the condition is vacuously true.
    if p + 1 >= v.len() {
        return true;
    }

    // Compute the maximum on the prefix [0..=p]
    let (max_prefix, _) = find_max_in_prefix(v, p);
    // Compute the minimum on the suffix [p+1..end]
    let (min_suffix, _) = find_min_in_suffix(v, p + 1);

    // The barrier condition holds iff max(prefix) < min(suffix)
    max_prefix < min_suffix
}

