        let v = [3, 1, 4, 2, 5];
        assert_eq!(find_max_in_prefix(&v, 0), (3, 0));
        assert_eq!(find_max_in_prefix(&v, 2), (4, 2));
        assert_eq!(find_max_in_prefix(&v, 4), (5, 4));
